  const s = String(x);
  let rev = '';
  for (let i = s.length - 1; i >= 0; i--) {
    rev += s[i];
  }
  return s === rev;
}

function solve(x) {
  if (x < 0) return false;
  if (x !== 0 && x % 10 === 0) return false;
  let cur = x;
  let rev = 0;
  while (cur > rev) {
    rev = rev * 10 + (cur % 10);
    cur = (cur - (cur % 10)) / 10;
  }
  return cur === rev || cur === (rev - (rev % 10)) / 10;
}
